export default function ProjectGallery({ initialProject }: { initialProject?: string }) {
  const [selected, setSelected] = useState<Project | undefined>(() => projects.find((p) => p.slug === initialProject));
  const opener = useRef<HTMLButtonElement | null>(null);
  useEffect(() => { setSelected(projects.find((p) => p.slug === initialProject)); }, [initialProject]);
  const select = (project: Project, button: HTMLButtonElement) => { opener.current = button; setSelected(project); };
  const back = () => { setSelected(undefined); requestAnimationFrame(() => opener.current?.focus({ preventScroll: true })); };
  return <div className={styles.desktopCatalog}>
    <div hidden={Boolean(selected)}><h1 className={styles.pageTitle}>Projects &amp; engineering labs</h1><p className={styles.pageIntro}>Source-backed projects, architecture notes and clearly labeled forks.</p><ProjectCatalog onSelect={select} /></div>
    {selected && <ProjectDetails project={selected} onBack={back} />}
  </div>;

isCompactViewport = () => {
    const { width, height } = getViewportMetrics();
    const coarse = typeof window !== 'undefined' && window.matchMedia?.('(pointer: coarse)').matches;
    return isCompactWindowViewport(width, height, coarse);
}

notifySizeChange = () => {
    if (this.isCompactViewport()) return;

const compact = this.isCompactViewport();
const fitted = {};
if (event?.type === 'resize' && !compact && viewportWidth && viewportHeight) {
    const width = Math.min(this.state.width, 100);
    const height = this.state.maximized ? percentOf(availableVertical, viewportHeight) : Math.min(this.state.height, percentOf(availableVertical, viewportHeight));
    const position = clampWindowPositionWithinViewport(this.state.position,
        { width: viewportWidth * width / 100, height: viewportHeight * height / 100 },
        { viewportWidth, viewportHeight, viewportLeft, viewportTop, topOffset: topInset, snapBottomInset, bottomInset: safeAreaBottom });
    if (position) { fitted.position = position; this.updateTransformVariables(this.getWindowNode(), position.x, position.y); }
    fitted.width = width;
    fitted.height = height;
}
this.setState({
    ...fitted,
    compact,
    compactBounds: compactWindowBounds({ width: viewportWidth, height: viewportHeight, left: viewportLeft, top: viewportTop }, topInset, snapBottomInset + safeAreaBottom, { left: measureSafeAreaInset('left'), right: measureSafeAreaInset('right') }),
    availableHeight: availableVertical,

/* A compact window is the same app and chrome, not a second mobile interface. */
.windowFrameCompact { border-radius: 0; transition: opacity var(--motion-fast) ease; }
.windowFrameCompact .windowTitlebar { min-height: 44px; height: 44px; cursor: default; }
.windowFrameCompact .windowControlButton { min-width: 44px; min-height: 44px; }

const Ubuntu = dynamic(() => import('../ubuntu'), {
  ssr: false,
  loading: () => <div role="status" className="flex h-screen items-center justify-center bg-ub-cool-grey text-white">Opening desktop application…</div>,
});
export default function PortfolioFrame({ children, active = 'about', title = 'Portfolio', projectSlug }: { children: ReactNode; active?: string; title?: string; projectSlug?: string }) {
  const appId = active === 'projects' ? 'project-gallery' : active === 'contact' ? 'contact' : 'about';
  const context = useMemo(() => projectSlug ? { projectSlug } : undefined, [projectSlug]);
  return <><Ubuntu initialApp={appId} initialContext={context} />
    <noscript><div className={styles.shell}><nav aria-label="Portfolio documents"><Link prefetch={false} href="/">Desktop</Link> · <Link prefetch={false} href="/about/">About Alex</Link> · <Link prefetch={false} href="/projects/">Projects</Link> · <Link prefetch={false} href="/contact/">Contact</Link></nav><main id="portfolio-main" aria-label={title} className={styles.content}>{children}</main></div></noscript>
  </>;

